window.kbPageData["views/entry/k-609bd9e660959bb2"] = {"key":"entry/k-609bd9e660959bb2","state":{"route":"entry/k-609bd9e660959bb2"},"node":{"id":"k-609bd9e660959bb2","mode":"k","title":"较大数额罚款的听证告知和申请","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["拟处较大数额罚款时应告知听证权，当事人要求听证的应组织听证"],"qs":["江苏 2023 B类 行测#17"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"行政机关拟作出较大数额罚款，应当在决定前告知当事人有要求听证的权利。当事人在法定期限内提出要求的，行政机关应当组织听证。","review":{"definition":"行政机关拟作出较大数额罚款，应当在决定前告知当事人有要求听证的权利。当事人在法定期限内提出要求的，行政机关应当组织听证。","explanation":"2019年4月1日起施行的市场监管听证规则，以对法人或其他组织罚款十万元以上作为告知听证权的一般标准，并允许适用地方的具体规定。拟罚整形公司30万元，市监局应当先告知听证权。按当时规则，当事人可在告知书送达回证上签署意见，也可在收到告知书后三个工作日内提出，逾期未要求视为放弃。A项所设的依职权主动启动缺乏该程序依据，原案中的整形公司实际提出了听证申请。","references":[{"source":"web-e8eecec5f03b8474","location":"第四十二条","quote":"当事人要求听证的，行政机关应当组织听证"},{"source":"web-6a0c07ac6db00b4d","location":"第五条第三项、第七条","quote":"未要求举行听证的，视为放弃此权利"},{"source":"web-cde30711fb270fec","location":"转载判决书，二审法院认为","quote":"收到听证告知书后申请要求听证"}],"evidence":"区市场监管局在整形公司未申请的情况下可以主动组织听证","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2023 B类 行测#17":{"paper":"江苏 2023 B类 行测","n":17,"mod":"常识判断","src":["22262c34d18cd68fbee4.pdf",3],"asrc":["b08f2713d73015eac675.pdf",7],"card":"46c0d47c902fde44cdbb48f7","links":[{"id":"k-609bd9e660959bb2","role":"解题依据","why":"用于判断本案听证的启动条件。"}]}},"terms":{},"references":{"web-e8eecec5f03b8474":{"name":"《中华人民共和国行政处罚法》（2019年适用文本）","url":"https://qhca.miit.gov.cn/zwgk/zcwj/flfg/art/2022/art_68cb9f81db24484e98a6449590b6075a.html"},"web-6a0c07ac6db00b4d":{"name":"《市场监督管理行政处罚听证暂行办法》（总局令第3号）","url":"https://www.samr.gov.cn/fgs/sjdt/art/2023/art_ae69d592d7754de6b4644f1f7b780521.html"},"web-cde30711fb270fec":{"name":"淮安市中级人民法院（2020）苏08行终127号行政判决书","url":"https://m.thepaper.cn/newsDetail_forward_10911756"}},"topics":[],"units":{"k-609bd9e660959bb2":[["江苏 2023 B类 行测#17"]]}};
